// Bubble (free plan) sends the full author + books payload. Bubble's ':format as text'
// output is loose, so normalise everything here: numbers may be strings, null may be "",
// dates may be ISO, YYYY-MM-DD, MM/DD/YYYY or Bubble's default "Oct 15, 2025 12:00 am",
// available_on may be an array or a comma-separated string, books may be a JSON string.
const cfg = $('Config').first().json;
let body = $('Webhook').first().json.body ?? {};
const problems = [];

function parseMaybeJson(v, label) {
  if (typeof v !== 'string') return v;
  const s = v.trim();
  if (!s) return undefined;
  try { return JSON.parse(s); } catch (e) { problems.push(`${label} is not valid JSON`); return undefined; }
}
const str = (v) => (v === undefined || v === null ? '' : String(v).trim());
const pad = (n) => String(n).padStart(2, '0');
const istDay = (d) => new Date(d.getTime() + 330 * 60000).toISOString().slice(0, 10);

// Returns 'YYYY-MM-DD', null for empty, or undefined if it can't be read.
function toDay(v) {
  const s = str(v);
  if (!s || s.toLowerCase() === 'null') return null;
  let m;
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  if (/^\d{4}-\d{2}-\d{2}T/.test(s)) { const d = new Date(s); return isNaN(d) ? undefined : istDay(d); }
  if ((m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2}|\d{4})\b/))) {
    const y = m[3].length === 2 ? 2000 + Number(m[3]) : Number(m[3]);
    return `${y}-${pad(m[1])}-${pad(m[2])}`;
  }
  if (/^\d{10,13}$/.test(s)) { const n = Number(s); return istDay(new Date(s.length === 10 ? n * 1000 : n)); }
  const t = new Date(s.replace(/(\d)\s*(am|pm)$/i, '$1 $2'));
  if (isNaN(t)) return undefined;
  return `${t.getFullYear()}-${pad(t.getMonth() + 1)}-${pad(t.getDate())}`; // calendar date as written
}
// Returns a number, null for empty, or undefined if it isn't numeric.
function toNum(v) {
  if (typeof v === 'number') return Number.isFinite(v) ? v : undefined;
  const s = str(v);
  if (!s || s.toLowerCase() === 'null') return null;
  const n = Number(s.replace(/[₹,\s]/g, ''));
  return Number.isFinite(n) ? n : undefined;
}
function toList(v) {
  if (Array.isArray(v)) return v.map(str).filter(Boolean);
  const s = str(v);
  if (!s) return [];
  if (s.startsWith('[')) { try { return JSON.parse(s).map(str).filter(Boolean); } catch (e) {} }
  return s.split(',').map((x) => x.trim()).filter(Boolean);
}

body = parseMaybeJson(body, 'body') ?? {};
const author = parseMaybeJson(body.author, 'author') ?? {};
let books = parseMaybeJson(body.books, 'books');
if (books === undefined || books === null) books = [];
if (!Array.isArray(books)) { problems.push('books must be a list'); books = []; }

const request_id = str(body.request_id);
const log_id = str(body.log_id);
if (!request_id) problems.push('missing request_id');
if (request_id.length > 200) problems.push('request_id is too long');
if (!str(author.author_id)) problems.push('missing author.author_id');
if (!str(author.name)) problems.push('missing author.name');

let as_of_date = toDay(body.as_of_date);
if (as_of_date === undefined) problems.push(`as_of_date "${str(body.as_of_date)}" is not a date`);
if (!as_of_date) as_of_date = toDay(cfg.as_of_date);

const NUMS = ['mrp', 'copies_sold', 'royalty_earned', 'royalty_paid', 'royalty_pending'];
const DATES = ['publication_date', 'last_payout_date'];
const cleanBooks = books.map((raw, i) => {
  const b = parseMaybeJson(raw, `books[${i}]`) ?? {};
  const out = {
    book_id: str(b.book_id), title: str(b.title), isbn: str(b.isbn), genre: str(b.genre),
    status: str(b.status), print_partner: str(b.print_partner), available_on: toList(b.available_on),
  };
  const label = out.title || out.book_id || `#${i + 1}`;
  if (!out.title) problems.push(`book ${label} has no title`);
  if (!out.status) problems.push(`book ${label} has no status`);
  for (const k of NUMS) {
    const n = toNum(b[k]);
    if (n === undefined) problems.push(`book ${label}: ${k} "${str(b[k])}" is not a number`);
    out[k] = n ?? null;
  }
  for (const k of DATES) {
    const d = toDay(b[k]);
    if (d === undefined) problems.push(`book ${label}: ${k} "${str(b[k])}" is not a date`);
    out[k] = d ?? null;
  }
  return out;
});

return [{
  json: {
    valid: problems.length === 0,
    error: problems.length ? `Invalid request: ${problems.slice(0, 8).join('; ')}` : '',
    request_id, log_id, as_of_date,
    author: { author_id: str(author.author_id), name: str(author.name), email: str(author.email), city: str(author.city) },
    books: cleanBooks,
  },
}];

// Ignore an exact replay of a request_id seen in the last 10 minutes (e.g. a retried HTTP call).
// The primary double-click guard is the Bubble button condition. Static data persists only for
// production (active) executions and is saved when an execution finishes.
const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || {};
const now = Date.now();
const TTL_MS = 10 * 60 * 1000;
for (const [key, at] of Object.entries(sd.seen)) if (now - at > TTL_MS) delete sd.seen[key];

const p = $('Validate payload').first().json;
const replay = Boolean(sd.seen[p.request_id]);
if (!replay) sd.seen[p.request_id] = now;
return [{ json: { request_id: p.request_id, log_id: p.log_id, replay } }];

// All arithmetic and date logic happens here, deterministically. The AI only writes prose.
const p = $('Validate payload').first().json;
const asOf = p.as_of_date;
const books = p.books;
if (!/^\d{4}-\d{2}-\d{2}$/.test(String(asOf))) throw new Error('as_of_date must be YYYY-MM-DD');

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const num = (v) => Number(v) || 0;
const DAY = 864e5;
const daysBetween = (a, b) => Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / DAY);
function fmtDate(iso) {
  if (!iso) return null;
  const [y, m, d] = iso.split('-').map(Number);
  return `${d} ${MONTHS[m - 1]} ${y}`;
}
function inr(n) {
  n = Math.round(num(n));
  const neg = n < 0;
  const s = String(Math.abs(n));
  let last3 = s.slice(-3);
  let rest = s.slice(0, -3);
  if (rest) last3 = ',' + last3;
  rest = rest.replace(/\B(?=(\d{2})+(?!\d))/g, ',');
  return (neg ? '-' : '') + '₹' + rest + last3;
}
const isPublished = (s) => /published/i.test(String(s ?? '')) && !/production/i.test(String(s ?? ''));
function stageOf(s) {
  const tail = String(s ?? '').split(/\s-\s|___/).pop() || '';
  return tail.replace(/_/g, ' ').trim().replace(/\b\w/g, (c) => c.toUpperCase());
}
function nextPayout(asOfIso) {
  const a = Date.parse(asOfIso + 'T00:00:00Z');
  const y = new Date(a).getUTCFullYear();
  const quarters = [[2, 31, 'Jan–Mar'], [5, 30, 'Apr–Jun'], [8, 30, 'Jul–Sep'], [11, 31, 'Oct–Dec']];
  let best = null;
  for (const yy of [y - 1, y, y + 1]) {
    for (const [m, d, label] of quarters) {
      const due = Date.UTC(yy, m, d) + 45 * DAY; // paid within 45 days of quarter end
      if (due >= a && (best === null || due < best.due)) best = { due, label: `${label} ${yy}` };
    }
  }
  const iso = new Date(best.due).toISOString().slice(0, 10);
  return { date: iso, display_date: fmtDate(iso), quarter_label: best.label };
}

const totals = { earned: 0, paid: 0, pending: 0, copies: 0 };
for (const b of books) {
  totals.earned += num(b.royalty_earned);
  totals.paid += num(b.royalty_paid);
  totals.pending += num(b.royalty_pending);
  totals.copies += num(b.copies_sold);
}

const published = [];
const production = [];
for (const b of books) {
  if (!isPublished(b.status)) {
    production.push({ title: b.title, stage: stageOf(b.status) });
    continue;
  }
  const pending = num(b.royalty_pending);
  let status = 'Paid up';
  if (pending > 0) {
    const ref = b.last_payout_date || b.publication_date;
    // Brief: overdue if pending and last payout > 90 days ago, or never paid and published > 90 days ago.
    // KB: totals under ₹1,000 roll over, so they are not overdue.
    status = ref && daysBetween(ref, asOf) > 90 && totals.pending >= 1000 ? 'Overdue' : 'Pending';
  }
  published.push({
    title: b.title,
    _pub: b.publication_date,
    copies_sold: num(b.copies_sold),
    royalty_earned: inr(b.royalty_earned),
    royalty_paid: inr(b.royalty_paid),
    royalty_pending: inr(pending),
    last_payout: b.last_payout_date ? fmtDate(b.last_payout_date) : 'no payout yet',
    payout_status: status,
  });
}
published.sort((a, b) => String(a._pub).localeCompare(String(b._pub)));

const flags = {
  all_paid: totals.pending === 0,
  has_pending: totals.pending > 0,
  below_threshold: totals.pending > 0 && totals.pending < 1000,
  has_overdue: published.some((b) => b.payout_status === 'Overdue'),
  has_production: production.length > 0,
};

return [{
  json: {
    author: { first_name: String(p.author.name).split(' ')[0], full_name: p.author.name, author_id: p.author.author_id },
    as_of_date: asOf,
    as_of_display: fmtDate(asOf),
    published_books: published.map(({ _pub, ...rest }) => rest),
    production_books: production,
    totals: { earned: inr(totals.earned), paid: inr(totals.paid), pending: inr(totals.pending), copies_sold: totals.copies },
    flags,
    next_payout: flags.has_pending && !flags.below_threshold ? nextPayout(asOf) : null,
    overdue_books: published.filter((b) => b.payout_status === 'Overdue').map((b) => b.title),
  },
}];

// Builds the Gemini generateContent request. Prompt text is documented in prompt.md.
const facts = $input.first().json;
const model = String($('Config').first().json.gemini_model || '');

const SYSTEM_PROMPT = "You write royalty summary emails for BookLeaf Publishing, a self-publishing company operating in India and the US. Each email goes to one author. Accuracy matters more than style.

BOOKLEAF ROYALTY POLICY (the only policy facts you may state)
- BookLeaf follows an 80/20 royalty split: 80% of the net profit per book goes to the author, 20% to BookLeaf.
- Net profit = MRP minus printing cost, platform commission (Amazon/Flipkart) and shipping charges.
- Royalties are calculated quarterly and paid within 45 days of the quarter ending.
- Minimum payout threshold: ₹1,000. If accumulated royalties are below this, they roll over to the next quarter.
- Payouts are made via bank transfer to the account linked in the author's dashboard.
- Authors can view a detailed royalty breakdown in their dashboard, showing sales figures per platform.
- Production stages: Manuscript Received → Editing (if opted) → Cover Design → Typesetting → Proofreading → ISBN Assignment → Printing → Distribution Setup → Published & Live. Authors are updated at each stage via email.

TONE (BookLeaf Communication Tone Guidelines)
- Always empathetic and professional. Authors are our partners, not customers to be managed.
- Be specific: include the actual numbers, dates and statuses you are given rather than vague reassurances.
- If something is BookLeaf's fault (for example a delayed royalty payout), own it directly. No corporate deflection.
- If something needs escalation or investigation, give a clear timeline: "Our team will look into this and get back to you within 48 hours." Never make open-ended promises.
- Always end with a clear next step for the author and/or the BookLeaf team.
- Plain text only: short paragraphs, no markdown, no emojis.

HARD RULES
1. Use only the facts in the AUTHOR DATA block. Never invent books, figures, dates, platforms, bank details or promises.
2. Copy every money figure and date exactly as written in AUTHOR DATA (they are already formatted, e.g. "₹13,024", "14 Feb 2026"). Do not recalculate, round or convert anything.
3. Never work out dates yourself. When a payout date is needed, use next_payout.display_date.
4. Do not mention internal field names, flags, JSON, status codes, or that you are an AI.
5. If a fact is missing, leave it out rather than guess.

EMAIL STRUCTURE (in this order; skip a section only when its condition is false)
1. Greeting with the author's first name, e.g. "Hi Priya,".
2. One opening line thanking them and giving the date the summary is as of (as_of_display).
3. Published books: one short line per published book with copies sold, royalty earned, paid, pending, and the last payout date (or "no payout yet").
4. Totals: total earned, total paid and total pending, each on its own line.
5. Payout outlook, exactly one of:
   - flags.all_paid is true: a warm, positive acknowledgement that they are fully paid up.
   - flags.below_threshold is true: explain that the pending amount is below the ₹1,000 minimum payout, so it rolls over to the next quarter and will be paid once their accumulated royalties reach ₹1,000.
   - otherwise: explain that royalties are calculated quarterly and paid within 45 days of the quarter ending, and that they can expect their pending amount by next_payout.display_date (for the next_payout.quarter_label quarter). If flags.has_overdue is true, also name the book(s) in overdue_books, say plainly that this payout is overdue and that this is on BookLeaf, and that our team will look into it and get back to them within 48 hours.
6. Only if flags.has_production is true: a brief update naming each book in production_books and its current stage, and saying we will keep them updated by email at each stage until it goes live.
7. Next step: invite them to reply to this email if any figure looks off, and mention that their dashboard shows the detailed breakdown.
8. Close warmly and sign off exactly as:
Warm regards,
Author Success Team
BookLeaf Publishing

OUTPUT
Return JSON only: {"subject": string, "body_text": string}
- subject: under 70 characters and specific (mention the pending amount, or that they are all paid up).
- body_text: the complete plain-text email, using \n for line breaks, roughly 150 to 350 words.";
const userPrompt = "Write the royalty summary email for this author.

AUTHOR DATA (JSON):
" + JSON.stringify(facts, null, 2);

// Bubble waits synchronously, so keep thinking minimal: 3.x Flash-Lite supports MINIMAL,
// 3.x Flash's lowest level is LOW, 2.5 Flash takes a zero budget, 2.0 has no thinking.
let thinkingConfig;
if (/^gemini-2\.0/.test(model)) thinkingConfig = undefined;
else if (/^gemini-2\./.test(model)) thinkingConfig = { thinkingBudget: 0 };
else if (/^gemini-3\.\d+-flash$/.test(model)) thinkingConfig = { thinkingLevel: 'LOW' };
else thinkingConfig = { thinkingLevel: 'MINIMAL' };

const gemini_request = {
  systemInstruction: { parts: [{ text: SYSTEM_PROMPT }] },
  contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
  generationConfig: {
    temperature: 0.4,
    maxOutputTokens: 2048, // includes thinking tokens
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: { subject: { type: 'STRING' }, body_text: { type: 'STRING' } },
      required: ['subject', 'body_text'],
    },
    ...(thinkingConfig ? { thinkingConfig } : {}),
  },
};
return [{ json: { gemini_request } }];

// Parse and sanity-check the AI output. Throwing sends the run down the failure path.
const r = $input.first().json;
const facts = $('Build royalty facts').first().json;

if (r.promptFeedback?.blockReason) throw new Error(`Gemini blocked the prompt (${r.promptFeedback.blockReason})`);
const cand = r.candidates?.[0];
if (!cand) throw new Error('Gemini returned no candidates');
if (cand.finishReason && cand.finishReason !== 'STOP') throw new Error(`Gemini stopped early (finishReason=${cand.finishReason})`);

const text = (cand.content?.parts ?? []).filter((p) => !p.thought).map((p) => p.text ?? '').join('').trim();
let parsed;
try {
  parsed = JSON.parse(text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, ''));
} catch (e) {
  throw new Error('Gemini response was not valid JSON');
}
const email_subject = String(parsed.subject ?? '').trim();
const email_body = String(parsed.body_text ?? '').trim();
if (!email_subject || !email_body) throw new Error('Gemini response is missing subject or body_text');

// Guardrail: the email must carry the real figures, not paraphrases or invented numbers.
const required = [facts.author.first_name, facts.totals.earned, facts.totals.paid, facts.totals.pending];
if (facts.next_payout) required.push(facts.next_payout.display_date);
const missing = required.filter((s) => s && !email_body.includes(s));
if (missing.length) throw new Error(`AI email failed validation, missing: ${missing.join(', ')}`);

return [{ json: { email_subject, email_body } }];

// Build the response Bubble writes into the NotificationLog. Every response
// (Success / Failed / Duplicate) has the same keys so Bubble's API Connector maps them once.
const p = $('Validate payload').first().json;
const email = $('Parse AI output').first().json;
const r = $input.first().json;
const sent = Array.isArray(r.accepted) && r.accepted.length > 0;
const smtpError = r.error ? (typeof r.error === 'string' ? r.error : r.error.message || 'SMTP error') : '';

return [{
  json: {
    response: {
      status: 'Success',
      email_subject: email.email_subject,
      email_body: email.email_body,
      email_sent: sent,
      error_message: smtpError ? `Summary generated, but the email was not sent: ${smtpError}` : '',
      failed_step: '',
      completed_at: new Date().toISOString(),
      request_id: p.request_id,
      log_id: p.log_id,
    },
  },
}];

// Every failure path ends here and is answered with HTTP 200 + status "Failed",
// so Bubble can always write the outcome to its NotificationLog.
const safe = (fn, fallback) => { try { return fn() ?? fallback; } catch (e) { return fallback; } };
const p = safe(() => $('Validate payload').first().json, {});
const raw = safe(() => $('Webhook').first().json.body, {});
const j = $input.first().json;

const LABELS = {
  'Validate payload': 'Request validation',
  'Payload valid?': 'Request validation',
  'Replay check': 'Duplicate check',
  'Build royalty facts': 'Calculating royalty figures',
  'Build AI prompt': 'Building AI prompt',
  'Generate with Gemini': 'AI generation (Gemini)',
  'Parse AI output': 'Checking AI output',
  'Build success response': 'Building response',
};
const step = LABELS[j.failed_step] || j.failed_step || 'Unknown step';

function describe(x) {
  const e = x.error;
  if (!e) return x.message || 'Unknown error';
  if (typeof e === 'string') return e;
  const code = e.httpCode || e.status || e.code;
  const text = [e.message, e.description].filter(Boolean).join(' | ') || JSON.stringify(e);
  return (code ? `[${code}] ` : '') + text;
}
const rawObj = typeof raw === 'object' && raw ? raw : {};

return [{
  json: {
    response: {
      status: 'Failed',
      email_subject: '',
      email_body: '',
      email_sent: false,
      error_message: `${step}: ${describe(j)}`.slice(0, 1000),
      failed_step: step,
      completed_at: new Date().toISOString(),
      request_id: p.request_id || String(rawObj.request_id ?? ''),
      log_id: p.log_id || String(rawObj.log_id ?? ''),
    },
  },
}];
